// ---- #392 遗留①②③：remove/update 清目录幽灵条目 + disconnect 显式 scope 定位 ----

{
  const dir = mkdtempSync(join(tmpdir(), "dsh-mcp-mgr2m-"));
  const prevHome = process.env.DSH_HOME;
  try {
    process.env.DSH_HOME = dir;
